let t = String($json.output || '');
t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
t = t.replace(/^\s*#{1,6}\s+(.+)$/gm, '<b>$1</b>');
t = t.replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
t = t.replace(/`([^`\n]+)`/g, '<code>$1</code>');
t = t.replace(/^\s*\|?\s*:?-{3,}.*$/gm, '');
t = t.replace(/^---+$/gm, '');
return { json: { text: t.trim() } };
